package com.adesa.attendance.vendor;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.interceptor.TransactionInterceptor;import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;import org.springframework.aop.framework.ProxyFactory;import org.springframework.core.io.ClassPathResource;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import com.fasterxml.jackson.databind.ObjectMapper;import com.adesa.attendance.employee.EmployeeRole;import com.adesa.attendance.security.AuthenticatedEmployee;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import static org.assertj.core.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true)
class VendorIntegrationTest {
 @Container static PostgreSQLContainer<?> pg=new PostgreSQLContainer<>("postgres:16-alpine");
 VendorService service;VendorAdmin admin;JdbcTemplate db;final UUID employee=UUID.randomUUID();
 @BeforeEach void setup()throws Exception{
  var root=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());var privileged=new JdbcTemplate(root);privileged.execute("drop schema if exists vendor_private cascade");privileged.execute("create table if not exists employees(id uuid primary key,email text,role text,is_active boolean)");privileged.execute("delete from employees");privileged.update("insert into employees values(?,'admin@example.test','ADMIN',true)",employee);privileged.update("insert into employees values(?,'hr@example.test','HR',true)",UUID.randomUUID());privileged.execute("do $$ begin if not exists(select from pg_roles where rolname='vendor_app') then create role vendor_app login nosuperuser nobypassrls password 'vendor_test_only';end if;end $$");
  try(var connection=root.getConnection();var statement=connection.createStatement()){statement.execute(new String(new ClassPathResource("db/migration/V22__private_vendor_management.sql").getInputStream().readAllBytes(),StandardCharsets.UTF_8));}
  privileged.execute("grant usage on schema vendor_private to vendor_app");privileged.execute("grant all on all tables in schema vendor_private to vendor_app");privileged.execute("grant all on all sequences in schema vendor_private to vendor_app");privileged.execute("grant select on employees to vendor_app");
  var ds=new DriverManagerDataSource(pg.getJdbcUrl(),"vendor_app","vendor_test_only");db=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);var crypto=new VendorCrypto(Base64.getEncoder().encodeToString(new byte[32]));service=proxied(new VendorService(db,new ObjectMapper(),crypto,true,true,"","http://localhost:5180"),manager,VendorService.class);admin=proxied(new VendorAdmin(service),manager,VendorAdmin.class);signIn(EmployeeRole.ADMIN);
 }
 private static <T>T proxied(T target,DataSourceTransactionManager manager,Class<T> type){var factory=new ProxyFactory(target);factory.setProxyTargetClass(true);factory.addAdvice(new TransactionInterceptor(manager,new AnnotationTransactionAttributeSource(false)));return type.cast(factory.getProxy());}
 private void signIn(EmployeeRole role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedEmployee(employee,role==EmployeeRole.ADMIN?"admin@example.test":"hr@example.test","Synthetic Staff",role),"",List.of(new SimpleGrantedAuthority("ROLE_"+role))));}
 private String link(String site){return String.valueOf(admin.createLink(Map.of("label","Integration link","kind","REUSABLE","subsidiary",site)).get("url")).split("#invite=")[1];}
 private String open(String token,String site){return String.valueOf(service.open(token,site,false).get("session"));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void completeSignedJourneyAndIndependentBankVerification(){String token=link("ENERGY");assertThatThrownBy(()->open(token,"MEDIA")).hasMessageContaining("another ADESA");String session=open(token,"ENERGY");var receipt=service.submit(session,"ENERGY",VendorDemoFixtures.sample(0,"ENERGY"));assertThat(receipt.get("status")).isEqualTo("PENDING_REVIEW");UUID id=UUID.fromString(String.valueOf(admin.applications().getFirst().get("id")));assertThat(admin.profile(id,1).get("eligibleForPayment")).isEqualTo(false);admin.status(id,"APPROVED","");assertThat(admin.profile(id,1).get("eligibleForPayment")).isEqualTo(false);admin.banking(id,"VERIFIED","Independent fictional bank check TX-DEMO");assertThat(admin.profile(id,1).get("eligibleForPayment")).isEqualTo(true);assertThat(admin.pdf(id,1)).startsWith("%PDF".getBytes(StandardCharsets.US_ASCII));assertThat(service.submit(session,"ENERGY",Map.of()).get("reference")).isEqualTo(receipt.get("reference"));}
 @Test void revokedLinksAndForeignDocumentsAreRejected(){String first=link("MEDIA"),second=link("MEDIA");String a=open(first,"MEDIA"),b=open(second,"MEDIA");byte[] image=VendorFiles.signature("Fictional Vendor","CLASSIC");UUID file=(UUID)service.uploadStart(a,"MEDIA",Map.of("filename","signature.png","category","SIGNATURE","size",image.length,"mime","image/png")).get("id");assertThatThrownBy(()->service.chunk(b,"MEDIA",file,Map.of("index",0,"data",Base64.getEncoder().encodeToString(image)))).hasMessageContaining("not found");UUID linkId=(UUID)admin.links().stream().filter(l->String.valueOf(l.get("url")).endsWith(first)).findFirst().orElseThrow().get("id");admin.linkState(linkId,"REVOKED");assertThatThrownBy(()->open(first,"MEDIA")).hasMessageContaining("revoked");assertThatThrownBy(()->service.state(a,"MEDIA")).hasMessageContaining("revoked");}
 @Test void correctionAppendsSignedRevisionAndResetsBankVerification(){String session=open(link("ENERGY"),"ENERGY");service.submit(session,"ENERGY",VendorDemoFixtures.sample(0,"ENERGY"));UUID id=(UUID)admin.applications().getFirst().get("id");admin.banking(id,"VERIFIED","Independent fictional check");String correction=String.valueOf(admin.request(id,"Update your fictional account and confirm again",7).get("url")).split("#request=")[1];String newSession=String.valueOf(service.open(correction,"ENERGY",true).get("session"));var changed=VendorDemoFixtures.sample(0,"ENERGY");changed.put("accountNumber","1111111111");service.submit(newSession,"ENERGY",changed);assertThat(admin.profile(id,0).get("current_revision")).isEqualTo(2);assertThat(admin.profile(id,0).get("banking_status")).isEqualTo("UNVERIFIED");assertThat(((Map<?,?>)admin.profile(id,1).get("answers")).get("accountNumber")).isEqualTo("0000000000");assertThatThrownBy(()->service.open(correction,"ENERGY",true)).hasMessageContaining("already completed");}
 @Test void hrCannotReadMetadataFilesSignaturesOrPdfsAndDefaultConnectionScopeIsEmpty(){service.submit(open(link("MEDIA"),"MEDIA"),"MEDIA",VendorDemoFixtures.sample(0,"MEDIA"));assertThat(db.queryForObject("select count(*) from vendor_private.application",Integer.class)).isZero();assertThat(db.queryForObject("select count(*) from vendor_private.document",Integer.class)).isZero();signIn(EmployeeRole.HR);assertThatThrownBy(admin::applications).hasMessageContaining("System Administrator");assertThatThrownBy(admin::links).hasMessageContaining("System Administrator");assertThatThrownBy(()->admin.pdf(UUID.randomUUID(),1)).hasMessageContaining("System Administrator");assertThatThrownBy(()->admin.documentTicket(UUID.randomUUID())).hasMessageContaining("System Administrator");}
}
